import json
import re
import unicodedata
from difflib import SequenceMatcher

# Paste the cluster log from the question between the triple quotes.
CLUSTER_LOG = r"""PASTE CLUSTER LOG HERE"""

# Ethno-racial labels are distinct from legal status and place names.
ETHNO_ALIASES = {
    "indio": "Indigenous",
    "india": "Indigenous",
    "indios": "Indigenous",
    "indigena": "Indigenous",
    "indigino": "Indigenous",
    "indigina": "Indigenous",
    "indijena": "Indigenous",
    "indijina": "Indigenous",
    "indijino": "Indigenous",
    "indo": "Indigenous",
    "id": "Indigenous",       # Domain-specific abbreviation
    "espanol": "Spanish",
    "espanola": "Spanish",
    "mestiza": "Mestizo",
}

STATUS_ALIASES = {
    "natural": "Natural",
    "naturales": "Natural",
    "legitimo": "Legitimate",
    "legitima": "Legitimate",
    "legitimos": "Legitimate",
    "espurio": "Spurious",
    "espuria": "Spurious",
}

# Expand these before token-level classification so the legal meaning survives.
ABBREVIATIONS = {
    "hn": ("hijo", "natural"),
    "hl": ("hijo", "legitimo"),
}

PLACES = {
    "aucara": "Aucara",
    "ishua": "Ishua",
    "pampamarca": "Pampamarca",
    "chacralla": "Chacralla",
    "punas": "Punas",
}

# These contextual words are preserved neither as facets nor as identities.
CONTEXT_WORDS = {
    "hijo", "hija", "hijos", "padre", "vecino", "tributario"
}


def fold(text):
    """Normalize case and diacritics without changing the original evidence."""
    text = unicodedata.normalize("NFD", text.lower())
    return "".join(c for c in text if unicodedata.category(c) != "Mn")


def close_alias(token, aliases, cutoff=0.84):
    """
    Conservative fallback for previously unlisted spellings.
    Ties or near-ties are rejected rather than silently guessed.
    """
    scores = sorted(
        ((SequenceMatcher(None, token, alias).ratio(), alias)
         for alias in aliases),
        reverse=True,
    )
    if not scores or scores[0][0] < cutoff:
        return None
    if len(scores) > 1 and scores[0][0] - scores[1][0] < 0.03:
        # Competing aliases may still have the same canonical meaning.
        if aliases[scores[0][1]] != aliases[scores[1][1]]:
            return None
    return aliases[scores[0][1]]


def classify_token(token):
    # Exact, domain-specific rules precede approximate matching.
    for facet, aliases in (
        ("Ethno-Racial Category", ETHNO_ALIASES),
        ("Legitimacy Status", STATUS_ALIASES),
        ("Geographic Location", PLACES),
    ):
        if token in aliases:
            return facet, aliases[token]

    # Only try fuzzy matching against ethno-racial spellings. Applying it
    # indiscriminately could turn an unknown place into an identity label.
    value = close_alias(token, ETHNO_ALIASES)
    if value is not None:
        return "Ethno-Racial Category", value
    return None


def normalize_term(term):
    facets = {
        "Ethno-Racial Category": set(),
        "Legitimacy Status": set(),
        "Geographic Location": set(),
    }
    unresolved = []

    tokens = re.findall(r"[a-z]+", fold(term))
    expanded = []
    for token in tokens:
        expanded.extend(ABBREVIATIONS.get(token, (token,)))

    for token in expanded:
        if token in CONTEXT_WORDS:
            continue
        result = classify_token(token)
        if result is None:
            unresolved.append(token)
        else:
            facet, value = result
            facets[facet].add(value)

    return {
        **{facet: sorted(values) for facet, values in facets.items()},
        "unresolved_tokens": unresolved,
    }


def parse_clusters(log):
    output = {}
    for line in log.splitlines():
        match = re.fullmatch(r"\s*Cluster\s+(\d+)\s*:\s*(.*?)\s*", line)
        if not match:
            continue
        cluster_id, keyword_list = match.groups()
        terms = [term.strip() for term in keyword_list.split(",") if term.strip()]
        records = [{"original": term, **normalize_term(term)} for term in terms]

        output[cluster_id] = {
            "terms": records,
            "facets": {
                facet: sorted({
                    value
                    for record in records
                    for value in record[facet]
                })
                for facet in (
                    "Ethno-Racial Category",
                    "Legitimacy Status",
                    "Geographic Location",
                )
            },
        }
    return output


if __name__ == "__main__":
    print(json.dumps(parse_clusters(CLUSTER_LOG), ensure_ascii=False, indent=2))
```

Orthographic variation in early modern Andean parish records is not simply a matter of misspelling. Clerks wrote within changing conventions for representing Spanish and Indigenous names, while handwriting, copying, and later transcription introduced further differences. Forms such as *indigena*, *indijena*, and *indigina* can point toward the same broad classification, but their differences remain evidence of how a particular record was produced. The script therefore retains every original keyword beside its normalized attributes. It also leaves unidentified tokens visible instead of forcing them into a category. That distinction matters when a doubtful reading might be a local place name, a label used by one scribe, or a transcription error requiring consultation of the manuscript.

Abbreviation makes the task harder because a short string carries meaning that cannot be recovered reliably from spelling alone. Here, `hn` and `hl` are expanded by explicit domain rules to *hijo natural* and *hijo legitimo*; `id` is treated as an abbreviation for *indigena*. The script then separates the legal status from the contextual word *hijo*. It likewise keeps an ethno-racial category separate from a geographic location: in *indio pampamarca*, the first token supplies a category and the second a place. This is a methodological choice, not a claim that every historical use of *indio* had a fixed or uncomplicated social meaning. In an archival project, the abbreviation table and place gazetteer should be checked against the collection’s own scribal practices.

String-distance methods are useful after those rules have established the interpretive boundaries. A Levenshtein-style comparison—or the script’s standard-library `SequenceMatcher` fallback—can recognize a previously unlisted variant near a known label. By itself, however, similarity cannot explain that `hl` denotes legitimacy, nor can it reliably distinguish an unfamiliar locality from a short identity term. Naive vector-space models face a related problem: keyword co-occurrence may place *hija*, *legitima*, and *aucara* close together without identifying which expresses kinship, legal status, or location. Rule-based taxonomies supply those distinctions; conservative approximate matching supplies limited tolerance for scribal variation. The resulting JSON is deterministic and auditable, while unresolved readings remain available for human review.

